contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount_, uint256 rate_, uint256 duration_) public {
        require(duration_ == 0 || rate_ <= type(uint256).max / duration_, "rate*duration overflow");
        uint256 rd = rate_ * duration_ / 365 days;
        require(amount_ == 0 || rd <= type(uint256).max / amount_, "amount*rd overflow");

        uint256 interest;
        bool reverted;
        uint256 v = c.interestFor(amount_, rate_, duration_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            interest = v;
            reverted = false;
        }

        uint256 expected = (amount_ * rd) / 1e18;
        assert(!reverted && interest == expected);
    }
}

