// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 rate_, uint256 duration_) internal {
        vm.assume(duration_ == 0 || rate_ <= type(uint256).max / duration_);
        uint256 rd = rate_ * duration_ / 365 days;
        vm.assume(amount_ == 0 || rd <= type(uint256).max / amount_);
        uint256 interest;
        bool reverted;
        try c.interestFor(amount_, rate_, duration_) returns (uint256 v) {
            interest = v;
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 expected = (amount_ * rd) / 1e18;
        assertTrue(!reverted && interest == expected);
    }

    function testFuzz_run(uint256 amount_, uint256 rate_, uint256 duration_) public {
        _run(amount_, rate_, duration_);
    }

    receive() external payable {}
}
